<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Etichette EA Express</title>@vite(['resources/js/labels.js'])<style>body{font:14px system-ui;margin:0;background:#eee;color:#111}.tools{padding:20px;text-align:center}.label{box-sizing:border-box;width:105mm;min-height:148mm;padding:8mm;background:white;margin:12px auto;overflow-wrap:anywhere;border:1px solid #bbb}.brand{font-size:25px;font-weight:800;border-bottom:3px solid #111;padding-bottom:8px}.reference{font:700 16px monospace;margin:12px 0}.section{border-top:1px solid #aaa;padding-top:10px;margin-top:10px}.label h2{font-size:11px;text-transform:uppercase}.recipient{font-size:19px;font-weight:700}.fragile{font-size:24px;font-weight:900;border:3px solid;padding:4px;text-align:center}@page{size:105mm 148mm;margin:0}@media print{body{background:white}.tools{display:none}.label{border:0;margin:0;min-height:0;height:148mm;break-after:page;break-inside:avoid}.label:last-child{break-after:auto}}@media screen and (max-width:420px){.label{width:100%;min-height:0}}</style></head><body><div class="tools"><button type="button" data-print-labels>Stampa tutte le etichette</button><p>{{ $orders->count() }} spedizioni · {{ $orders->sum('parcel_count') }} colli · formato A6</p></div>@foreach($orders as $order)<article class="label"><div class="brand">EA EXPRESS</div><div class="reference">{{ $order->reference }}</div><strong>Colli: {{ $order->parcel_count }}</strong><div class="section"><h2>Destinatario</h2><div class="recipient">{{ $order->recipient_name }}</div><p>{{ $order->delivery_address }} {{ $order->delivery_street_number }}<br>{{ $order->delivery_postal_code }} {{ $order->delivery_city }}<br>Tel. {{ $order->recipient_phone }}</p></div><div class="section"><h2>Mittente / ritiro</h2><strong>{{ $order->store_name }}</strong><p>{{ $order->pickup_address }} {{ $order->pickup_street_number }}<br>{{ $order->pickup_postal_code }} {{ $order->pickup_city }}<br>{{ $order->pickup_date->format('d/m/Y') }} · {{ $order->pickup_from }}–{{ $order->pickup_to }}</p></div>@if($order->package_type==='fragile')<div class="fragile">FRAGILE</div>@elseif($order->package_type==='other')<p>{{ $order->package_description }}</p>@endif</article>@endforeach</body></html>